1	package sem
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"os"
7		"path/filepath"
8		"regexp"
9		"sort"
10		"strings"
11		"testing"
12	)
13	
14	// The Vue corpus is two realistic Vue applications with a hand-written ground
15	// truth (testdata/vuecorpus/<app>/expected.json). It measures how much of a
16	// correct Vue graph the provider emits, tag by tag, and ratchets the result in
17	// testdata/vuecorpus/score.json. See testdata/vuecorpus/README.md.
18	var vueCorpusApps = []string{"helpdesk", "taskboard"}
19	
20	const vueCorpusRoot = "testdata/vuecorpus"
21	
22	type vueCorpusEndpoint struct {
23		File     string `json:"file,omitempty"`
24		Name     string `json:"name,omitempty"`
25		Kind     string `json:"kind,omitempty"`
26		External string `json:"external,omitempty"`
27	}
28	
29	func (e vueCorpusEndpoint) key() string {
30		switch {
31		case e.External != "":
32			return "ext:" + e.External
33		case e.Name == "":
34			return e.File
35		case e.Kind != "":
36			return e.File + "#" + e.Name + ":" + e.Kind
37		default:
38			return e.File + "#" + e.Name
39		}
40	}
