59	type vueCorpusSymbol struct {
60		File string `json:"file"`
61		Name string `json:"name"`
62		Kind string `json:"kind,omitempty"`
63		Line int    `json:"line"`
64		Tag  string `json:"tag"`
65	}
66	
67	type vueCorpusAbsent struct {
68		File string `json:"file"`
69		Name string `json:"name"`
70		Kind string `json:"kind,omitempty"`
71		Tag  string `json:"tag"`
72		Why  string `json:"why"`
73	}
74	
75	type vueCorpusRelation struct {
76		Type vueCorpusTypes    `json:"type"`
77		From vueCorpusEndpoint `json:"from"`
78		To   vueCorpusEndpoint `json:"to"`
79		Tag  string            `json:"tag"`
80		Note string            `json:"note,omitempty"`
81	}
