83	type vueCorpusManifest struct {
84		App           string              `json:"app"`
85		Description   string              `json:"description,omitempty"`
86		Symbols       []vueCorpusSymbol   `json:"symbols"`
87		AbsentSymbols []vueCorpusAbsent   `json:"absent_symbols"`
88		Relations     []vueCorpusRelation `json:"relations"`
89	}
90	
91	var vueCorpusTags = map[string]bool{
92		"baseline": true, "script-symbols": true, "script-imports": true, "script-calls": true,
93		"component-owner": true, "false-elements": true, "template-edges": true, "options-api": true,
94		"store-members": true, "path-alias": true, "lazy-imports": true, "global-registration": true,
95		"ts-types": true, "mixins": true, "event-bus": true, "tests": true, "script-src": true,
96	}
97	
98	func loadVueCorpusManifest(t *testing.T, app string) vueCorpusManifest {
99		t.Helper()
100		data, err := os.ReadFile(filepath.Join(vueCorpusRoot, app, "expected.json"))
101		if err != nil {
102			t.Fatalf("read %s manifest: %v", app, err)
103		}
104		var manifest vueCorpusManifest
105		decoder := json.NewDecoder(strings.NewReader(string(data)))
106		decoder.DisallowUnknownFields()
107		if err := decoder.Decode(&manifest); err != nil {
108			t.Fatalf("parse %s manifest: %v", app, err)
109		}
110		return manifest
111	}
112	
113	func vueCorpusSymbolKey(file, name, kind string) string {
114		if kind != "" {
115			return "symbol " + file + "#" + name + ":" + kind
116		}
117		return "symbol " + file + "#" + name
118	}
119	
120	func (r vueCorpusRelation) key() string {
121		return strings.Join(r.Type, "|") + " " + r.From.key() + " -> " + r.To.key()
122	}
