import tickets from '@/store/modules/tickets'
import { fetchTicketList } from '@/api/tickets'

jest.mock('@/api/tickets')

describe('tickets store module', () => {
  it('SET_TICKETS replaces the list and the total', () => {
    const state = tickets.state()
    tickets.mutations.SET_TICKETS(state, { items: [{ id: 1 }, { id: 2 }], total: 2 })
    expect(state.items).toHaveLength(2)
    expect(state.total).toBe(2)
  })

  it('openTickets leaves out closed tickets', () => {
    const state = tickets.state()
    state.items = [{ id: 1, status: 'open' }, { id: 2, status: 'closed' }]
    expect(tickets.getters.openTickets(state)).toEqual([{ id: 1, status: 'open' }])
  })

  it('fetchTickets merges filters into the request and commits the result', async () => {
    const result = { items: [{ id: 7 }], total: 1 }
    fetchTicketList.mockResolvedValue(result)
    const commit = jest.fn()
    const state = tickets.state()

    await tickets.actions.fetchTickets({ commit, state }, { page: 2 })

    expect(fetchTicketList).toHaveBeenCalledWith(expect.objectContaining({ status: 'open', page: 2 }))
    expect(commit).toHaveBeenCalledWith('SET_TICKETS', result)
    expect(commit).toHaveBeenLastCalledWith('SET_LOADING', false)
  })

  it('applyFilters resets to the first page', async () => {
    const commit = jest.fn()
    const dispatch = jest.fn().mockResolvedValue(null)

    await tickets.actions.applyFilters({ commit, dispatch }, { priority: 'urgent' })

    expect(commit).toHaveBeenCalledWith('SET_FILTERS', { priority: 'urgent' })
    expect(dispatch).toHaveBeenCalledWith('fetchTickets', { page: 1 })
  })
})

import { shallowMount } from '@vue/test-utils'
import { paginationMixin } from '@/mixins/paginationMixin'

function mountPaged(total) {
  return shallowMount({
    template: '<div />',
    mixins: [paginationMixin],
    data() {
      return { fetched: [] }
    },
    created() {
      this.setTotal(total)
    },
    methods: {
      fetchPage() {
        this.fetched.push(this.page)
        return Promise.resolve()
      }
    }
  })
}

describe('paginationMixin', () => {
  it('computes the page count from the total', () => {
    const wrapper = mountPaged(120)
    expect(wrapper.vm.totalPages).toBe(5)
  })

  it('nextPage advances and fetches', async () => {
    const wrapper = mountPaged(60)
    await wrapper.vm.nextPage()
    expect(wrapper.vm.page).toBe(2)
    expect(wrapper.vm.fetched).toEqual([2])
  })

  it('goToPage clamps to the last page', async () => {
    const wrapper = mountPaged(30)
    await wrapper.vm.goToPage(9)
    expect(wrapper.vm.page).toBe(2)
  })
})

import { isBreached, minutesRemaining, slaStatus } from '@/utils/sla'

const CREATED = new Date('2024-03-01T09:00:00Z').getTime()

describe('sla utils', () => {
  it('counts down from the priority target', () => {
    const ticket = { createdAt: CREATED, priority: 'high' }
    expect(minutesRemaining(ticket, CREATED + 20 * 60000)).toBe(100)
  })

  it('stops counting once the ticket has a first response', () => {
    const ticket = { createdAt: CREATED, priority: 'urgent', firstRespondedAt: CREATED + 60000 }
    expect(minutesRemaining(ticket, CREATED + 90 * 60000)).toBeNull()
    expect(slaStatus(ticket, CREATED + 90 * 60000)).toBe('met')
  })

  it('reports a breach after the deadline', () => {
    const ticket = { createdAt: CREATED, priority: 'urgent' }
    expect(isBreached(ticket, CREATED + 31 * 60000)).toBe(true)
    expect(slaStatus(ticket, CREATED + 10 * 60000)).toBe('at-risk')
  })
})

