import os, re
root='.'
bad=[]
for d,_,fs in os.walk(root):
    for f in fs:
        p=os.path.join(d,f)
        data=open(p,'rb').read()
        if any(b>127 for b in data): bad.append(('non-ascii',p))
        if b'\r' in data: bad.append(('crlf',p))
        if not data.endswith(b'\n'): bad.append(('no-final-newline',p))
