        specs+=re.findall(r'<script\s+src="([^"]+)"', text)
        for s in specs:
            if s.startswith('@/'):
                base=os.path.join('src', s[2:])
            elif s.startswith('.'):
                base=os.path.normpath(os.path.join(d, s))
            else:
                continue
            cands=[base, base+'.js', base+'.vue', os.path.join(base,'index.js')]
            if not any(os.path.isfile(c) for c in cands):
                bad.append(('unresolved', p, s))
